alter table public.social_accounts add column if not exists external_id text;
alter table public.social_accounts add column if not exists display_name text;
alter table public.social_accounts add column if not exists username text;
alter table public.social_accounts add column if not exists avatar_url text;
alter table public.social_accounts add column if not exists parent_account_id uuid references public.social_accounts(id) on delete set null;
alter table public.social_accounts add column if not exists token_expires_at timestamptz;
alter table public.social_accounts add column if not exists scopes text[] not null default '{}';
alter table public.social_accounts add column if not exists status text not null default 'active' check (status in ('active','expired','permission_required','disconnected'));
create unique index if not exists social_accounts_external_idx on public.social_accounts(workspace_id, platform, external_id);
create table if not exists public.scheduled_posts (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.workspaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, platform text not null, account_id uuid not null references public.social_accounts(id) on delete cascade, content text not null, media jsonb not null default '[]', scheduled_at timestamptz not null, status text not null default 'DRAFT' check (status in ('DRAFT','SCHEDULED','PUBLISHING','PUBLISHED','FAILED','CANCELLED')), attempts integer not null default 0, published_at timestamptz, external_post_id text, external_url text, error text, idempotency_key text not null unique, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()));
create table if not exists public.publishing_attempts (id uuid primary key default gen_random_uuid(), scheduled_post_id uuid not null references public.scheduled_posts(id) on delete cascade, attempt integer not null, status text not null, error_code text, error_message text, created_at timestamptz not null default timezone('utc',now()));
create table if not exists public.analytics_cache (id uuid primary key default gen_random_uuid(), social_account_id uuid not null references public.social_accounts(id) on delete cascade, metric_date date not null, payload jsonb not null, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()), unique(social_account_id,metric_date));
alter table public.scheduled_posts enable row level security; alter table public.publishing_attempts enable row level security; alter table public.analytics_cache enable row level security;
create policy "scheduled workspace isolation" on public.scheduled_posts for all using (public.is_workspace_member(workspace_id)) with check (public.is_workspace_member(workspace_id));
create policy "attempt workspace isolation" on public.publishing_attempts for all using (exists(select 1 from public.scheduled_posts p where p.id=scheduled_post_id and public.is_workspace_member(p.workspace_id))) with check (exists(select 1 from public.scheduled_posts p where p.id=scheduled_post_id and public.is_workspace_member(p.workspace_id)));
create policy "analytics workspace isolation" on public.analytics_cache for all using (exists(select 1 from public.social_accounts a where a.id=social_account_id and public.is_workspace_member(a.workspace_id))) with check (exists(select 1 from public.social_accounts a where a.id=social_account_id and public.is_workspace_member(a.workspace_id)));
